const cfg=$('Reminder Config').first().json;const cutoff=$now.minus({hours:24});const rows=$input.all().map(i=>i.json);const stale=rows.filter(r=>{const status=String(r.status||'').toLowerCase();if(status!=='new')return false;const created=r.created_at?DateTime.fromISO(String(r.created_at)):null;return created&&created.isValid&&created<cutoff;});const lines=stale.map(r=>`- ${r.patient_name||'(no name)'} | ${r.phone||'-'} | ${r.requested_service||'-'} | created ${r.created_at}`);const body=stale.length?`The following appointment leads are still marked "New" after 24h and need follow-up:

${lines.join('
')}

Please update their status once actioned.`:'';return[{json:{should_send:stale.length>0,count:stale.length,to:cfg.staff_email,clinic_name:cfg.clinic_name,body}}];

const ctx=$('Build Context').first().json; const p=ctx.patient;
const phone=(p.phone||'').replace(/\D/g,''); const email=(p.email||'').trim().toLowerCase();
const rows=$input.all().map(i=>i.json).filter(r=>r && (r.patient_key||r.phone||r.email));
let match=null;
if(phone && phone.length>=7){match=rows.find(r=>String(r.phone||'').replace(/\D/g,'')===phone);}
if(!match && email){match=rows.find(r=>String(r.email||'').trim().toLowerCase()===email);}
const hasContact=!!(phone||email);
const isExisting=!!match;
const patientKey=phone||email||'';
const created_at=(match&&match.created_at)||ctx.timestamp;
const patient_type=isExisting?'Existing':(hasContact?'New':(p.patient_type||''));
const merged={...ctx, patient:{...p, patient_type}, is_returning:isExisting, has_contact:hasContact, patient_key:patientKey};
const record={sheet_id:ctx.clinic.sheet_id, patient_key:patientKey, created_at, last_interaction:ctx.timestamp, first_name:p.first_name, last_name:p.last_name, email:p.email, phone:p.phone, service_required:p.service, patient_type, last_conversation_summary:(ctx.clinic.test_mode?'[TEST] ':'')+ctx.summary, status:'Active', notes:''};
return [{json:{...merged, _record:record}}];

