const ctx=$('Context Ready').first().json; const dec=$('APT_AI').first().json.output ?? $('APT_AI').first().json; const p=ctx.patient;
const start=dec.appointment_start_iso; const dur=ctx.clinic.appointment_duration_min||60;
const end=DateTime.fromISO(start).plus({minutes:dur}).toISO();
const events=$input.all().map(i=>i.json).filter(e=>e && (e.id||e.start));
const free=events.length===0;
return [{json:{...ctx, _booking:{ start, end, free, summary:`(TENTATIVE) Dental appt - ${p.name}`, description:`Tentative booking via chatbot. Service: ${p.service||'-'}. Phone: ${p.phone||'-'}. Email: ${p.email||'-'}. NOT staff-confirmed.`, attendee:p.email||'' }}}];

const ctx=$('APT_Slot').first().json; const b=ctx._booking;
const when=DateTime.fromISO(b.start).toFormat('cccc, LLL d, t');
const reply=`Thanks! I've tentatively held ${when} for you. This is not yet a confirmed booking \u2014 our team will review and confirm it shortly, and we'll be in touch if anything needs to change.`;
const c={...ctx}; delete c._booking; return {json:{...c, bot_response:reply}};

const ctx=$('APT_Slot').first().json; const b=ctx._booking;
const when=DateTime.fromISO(b.start).toFormat('cccc, LLL d, t');
const reply=`I'm sorry \u2014 ${when} isn't available. Could you share another date and time that works? I've also passed your request to our team, who can suggest openings.`;
const c={...ctx}; delete c._booking; return {json:{...c, bot_response:reply}};

