const ctx=$('Context Ready').item.json; const p=ctx.patient; const dec=$json.output??$json;
const reqType=ctx.intent==='reschedule_request'?'reschedule':'cancellation'; const day=$now.format('yyyy-LL-dd');
return {json:{ sheet_id:ctx.clinic.sheet_id, lead_key:`${ctx.clinic.clinic_id}|${p.phone||p.email||'nocontact'}|${reqType}|${day}`, created_at:ctx.timestamp, session_id:ctx.session_id, patient_name:p.name, phone:p.phone, email:p.email, request_type:reqType, existing_appt_datetime:p.existing_appt_datetime, new_preferred_datetime:dec.new_start_iso||p.new_preferred_datetime, reason:p.reason, status:dec.status||'Collecting', staff_notified:!!dec.notify_staff, sms_sent:false, notes:(ctx.clinic.test_mode?'[TEST] ':'')+ctx.summary }};

const ctx=$('Context Ready').first().json; const p=ctx.patient; const dec=$('CR_AI').first().json.output ?? $('CR_AI').first().json;
const email=(p.email||'').toLowerCase(); const phone=(p.phone||'').replace(/\D/g,'');
const events=$input.all().map(i=>i.json);
let match=null;
for(const e of events){ const att=JSON.stringify(e.attendees||'').toLowerCase(); const blob=`${e.summary||''} ${e.description||''}`.toLowerCase();
  if(email && (att.includes(email)||blob.includes(email))){match=e;break;}
  if(phone && blob.replace(/\D/g,'').includes(phone)){match=e;break;} }
const cutoff=ctx.clinic.change_cutoff_hours||48;
let found=!!match, within=false, eventId='', startIso='';
if(match){ startIso=(match.start&&(match.start.dateTime||match.start.date))||match.start||''; eventId=match.id||''; try{const hrs=DateTime.fromISO(startIso).diff($now,'hours').hours; within=hrs<cutoff;}catch(e){within=true;} }
const action=ctx.intent==='reschedule_request'?'reschedule':'cancellation';
const newStart=dec.new_start_iso||'';
const dur=ctx.clinic.appointment_duration_min||60;
const newEnd=newStart?DateTime.fromISO(newStart).plus({minutes:dur}).toISO():'';
const needsStaff = within || !found || (action==='reschedule' && !newStart);
return [{json:{...ctx, _cr:{ found, within, needsStaff, eventId, startIso, action, newStart, newEnd }}}];

const ctx=$('Context Ready').first().json; const cr=$('CR_Compute').first().json._cr; const p=ctx.patient;
const day=$now.format('yyyy-LL-dd');
const reasonTxt = cr.within ? `within ${ctx.clinic.change_cutoff_hours}h of the appointment` : (!cr.found ? 'appointment could not be located automatically' : 'missing new time for reschedule');
const _row={ sheet_id:ctx.clinic.sheet_id, lead_key:`${ctx.clinic.clinic_id}|${p.phone||p.email||'nocontact'}|${cr.action}_staff|${day}`, timestamp:ctx.timestamp, session_id:ctx.session_id, patient_name:p.name, phone:p.phone, email:p.email, issue_type:`${cr.action}_needs_staff`, urgency:cr.within?'high':'medium', summary:(ctx.clinic.test_mode?'[TEST] ':'')+`${cr.action} request — ${reasonTxt}. ${ctx.summary||''}`, staff_notified:true, sms_sent:false, status:'New', notes:cr.startIso?`Existing appt: ${cr.startIso}`:'' };
const _email={ to:ctx.clinic.staff_email, subject:`[${ctx.clinic.clinic_name}] STAFF ACTION — ${cr.action} (${reasonTxt}) — ${p.name}`, body:(ctx.clinic.test_mode?'[TEST MODE]
':'')+`A ${cr.action} request needs staff handling because it is ${reasonTxt}.

Patient: ${p.name}
Phone: ${p.phone||'-'}
Email: ${p.email||'-'}
Existing appointment: ${cr.startIso||'not found'}
Requested new time: ${cr.newStart||'-'}
Original message: "${ctx.user_message}"

Please action in the calendar and contact the patient.`, reply_to:p.email||'' };
const reply = cr.within ? `Thanks ${p.first_name||''}. Because your appointment is within ${ctx.clinic.change_cutoff_hours} hours, our team will handle this change directly and confirm with you shortly.` : `Thanks ${p.first_name||''}. I've passed your request to our team, who will take care of it and confirm with you shortly.`;
return [{json:{...ctx, _row, _email, _reply:reply}}];

const ctx=$('Context Ready').item.json; const cr=$('CR_Compute').first().json._cr;
const when=cr.startIso?DateTime.fromISO(cr.startIso).toFormat('cccc, LLL d, t'):'your appointment';
return {json:{...ctx, bot_response:`Done \u2014 I've cancelled ${when}. If that's not what you wanted, let me know and I'll flag it to our team.`}};

const ctx=$('Context Ready').item.json; const cr=$('CR_Compute').first().json._cr;
const when=cr.newStart?DateTime.fromISO(cr.newStart).toFormat('cccc, LLL d, t'):'the new time';
return {json:{...ctx, bot_response:`Done \u2014 I've moved your appointment to ${when} (tentatively). Our team will confirm; let us know if anything's off.`}};
